// Normalises the farm context the frontend supplied and decides which
// agents are worth calling at all.
//
// n8n never reads Supabase here: everything about the farm arrives in
// the request, already scoped to the signed-in farmer by row-level
// security on the frontend's own queries. That keeps this workflow
// holding no database credential.
//
// Readiness is computed rather than discovered by failure: calling
// Weather - Core with no coordinates would burn a round trip to learn
// something the farm record already told us, and would report "the
// weather service failed" when the truth is "this farm has no location
// saved" — a difference the farmer can act on.

const input = $input.first() ? $input.first().json : {};

const text = (v) => (typeof v === "string" && v.trim() !== "" ? v.trim() : null);

const num = (v) => {
  if (typeof v === "number" && Number.isFinite(v)) return v;
  if (typeof v === "string" && v.trim() !== "" && Number.isFinite(Number(v))) return Number(v);
  return null;
};

// Arrays arrive JSON-stringified because Execute Workflow stringifies
// its inputs. Anything unparseable degrades to empty rather than
// throwing — a missing scan list is a thinner briefing, not an error.
const parseArray = (v) => {
  let raw = v;
  if (typeof raw === "string") {
    const s = raw.trim();
    if (s === "") return [];
    try {
      raw = JSON.parse(s);
    } catch (e) {
      return [];
    }
  }
  return Array.isArray(raw) ? raw : [];
};

const parseObject = (v) => {
  let raw = v;
  if (typeof raw === "string") {
    const s = raw.trim();
    if (s === "" || s === "null") return null;
    try {
      raw = JSON.parse(s);
    } catch (e) {
      return null;
    }
  }
  return raw && typeof raw === "object" && !Array.isArray(raw) ? raw : null;
};

const state = text(input.state);
const district = text(input.district);
const latitude = num(input.latitude);
const longitude = num(input.longitude);
const crops = parseArray(input.crops).map((c) => text(c)).filter((c) => c !== null);
const primaryCrop = text(input.primaryCrop) || (crops.length > 0 ? crops[0] : null);

const rawScans = parseArray(input.recentScans);
// Only the fields the rules are permitted to use. The disease label and
// disclaimer text are never sent by the frontend and are not accepted
// here either, so no rule can turn a diagnosis into a treatment.
const recentScans = [];
for (const s of rawScans) {
  if (!s || typeof s !== "object") continue;
  const createdAt = text(s.createdAt);
  if (!createdAt) continue;
  recentScans.push({
    scanId: text(s.scanId),
    cropName: text(s.cropName),
    createdAt,
    category: text(s.category),
    confidenceLevel: text(s.confidenceLevel),
    recommendExpertConsult: s.recommendExpertConsult === true
  });
}
recentScans.sort((a, b) => (a.createdAt < b.createdAt ? 1 : a.createdAt > b.createdAt ? -1 : 0));

const rawSoil = parseObject(input.latestSoil);
// Presence and age only — NPK and pH are deliberately not part of this
// contract, so soil chemistry cannot become advice.
const latestSoil = rawSoil && text(rawSoil.testedOn) ? { testedOn: text(rawSoil.testedOn) } : null;

const context = {
  farmId: text(input.farmId),
  state,
  district,
  latitude,
  longitude,
  areaAcres: num(input.areaAcres),
  crops,
  primaryCrop,
  latestSoil,
  recentScans,
  locale: text(input.locale) || "en"
};

const weatherReady = latitude !== null && longitude !== null;
const marketReady = state !== null && district !== null && primaryCrop !== null;

return [
  {
    json: {
      context,
      contextJson: JSON.stringify(context),
      locale: context.locale,
      weatherReady,
      marketReady,
      weatherSkipReason: weatherReady ? null : "noCoordinates",
      marketSkipReason: !state || !district ? "noDistrict" : !primaryCrop ? "noCrop" : null
    }
  }
];

// Gathers the three agent branches into one signal bundle.
//
// The Merge upstream is a synchronisation join, not a data path: the
// branches are read here by node name instead, so each signal keeps its
// identity regardless of merge ordering or how many items a branch
// produced.
//
// A branch that never executed (its readiness gate sent flow to the Skip
// node) throws on access, which is caught and turned into a "skipped"
// signal carrying the reason the gate computed. A branch that ran but
// failed — every Call node has onError: continueRegularOutput — lands
// here as an item that is not a valid DataResult, and becomes
// "unavailable". One dead agent must never cost the farmer the whole
// briefing.

const inputs = $('Build Agent Inputs').first().json;

/** Reads one branch, never throwing. */
const readBranch = (nodeName) => {
  try {
    const item = $(nodeName).first();
    return item && item.json ? item.json : null;
  } catch (e) {
    return null;
  }
};

const toSignal = (payload, skipReason) => {
  if (payload === null) {
    return skipReason
      ? { status: "skipped", reasonKey: skipReason }
      : { status: "unavailable", reasonKey: "notConsulted" };
  }
  if (payload.status === "ok" && payload.data && typeof payload.data === "object") {
    return { status: "ok", asOf: payload.asOf || null, data: payload.data };
  }
  if (payload.status === "unavailable") {
    // The agent's own reason is a farmer-facing sentence; the briefing
    // renders a translated key instead, so only the fact is kept.
    return { status: "unavailable", reasonKey: "agentUnavailable" };
  }
  if (payload.status === "skipped") {
    return { status: "skipped", reasonKey: payload.reasonKey || "skipped" };
  }
  return { status: "unavailable", reasonKey: "agentUnavailable" };
};

const weatherCalled = readBranch("Call 'Weather - Core'");
const weatherSkipped = readBranch("Skip Weather");
const marketCalled = readBranch("Call 'Market - Core'");
const marketSkipped = readBranch("Skip Market");
const schemesCalled = readBranch("Call 'Schemes - Core'");

const signals = {
  weather: weatherCalled
    ? toSignal(weatherCalled, null)
    : toSignal(null, (weatherSkipped && weatherSkipped.reasonKey) || inputs.weatherSkipReason),
  market: marketCalled
    ? toSignal(marketCalled, null)
    : toSignal(null, (marketSkipped && marketSkipped.reasonKey) || inputs.marketSkipReason),
  schemes: toSignal(schemesCalled, null)
};

console.log(
  "Orchestrator signals:",
  JSON.stringify({
    weather: signals.weather.status,
    market: signals.market.status,
    schemes: signals.schemes.status
  })
);

return [
  {
    json: {
      signals: JSON.stringify(signals),
      context: inputs.contextJson,
      locale: inputs.locale
    }
  }
];
